INSERT INTO warscape_enemy_family VALUES (16,'dwarves','Dwarves','Ironforge mountaineer display 1598 with a Mining Pick; source level 20 deferred due rounded variant loot notes.');
INSERT INTO warscape_enemy_family VALUES (17,'pirates','Pirates','Defias/Bloodsail pirate displays 2347/793/796 with sword; quest pirates excluded.');
INSERT INTO warscape_enemy_family VALUES (18,'skeletons','Skeletons','Classic naked/armoured skeleton displays 11400/200, sword+shield for armed loot forms.');
INSERT INTO warscape_enemy_family VALUES (19,'zombies','Zombies','Plaguelands zombie/armed zombie displays 10973/1197.');
INSERT INTO warscape_enemy_family VALUES (20,'ghosts','Ghosts','Stock spectral Ghost model 11649; shrouded stand-in rather than custom translucent human.');
INSERT INTO warscape_enemy_family VALUES (21,'ghouls','Ghouls','Classic Scourge Ghoul display 137.');
INSERT INTO warscape_enemy_family VALUES (22,'hellhounds','Hellhounds','Stock Felhound display 1913, tier scales.');
INSERT INTO warscape_enemy_family VALUES (23,'minotaurs','Minotaurs','Male Grimtotem tauren displays 11874/11882 with axes as the horned humanoid stand-in.');
